17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
110	        this.clinicService.saveOwner(owner);
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
120	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
121	        if (currentOwner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        currentOwner.setAddress(ownerFieldsDto.getAddress());
125	        currentOwner.setCity(ownerFieldsDto.getCity());
126	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
127	        currentOwner.setLastName(ownerFieldsDto.getLastName());
128	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
129	        this.clinicService.saveOwner(currentOwner);
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Transactional
135	    @Override
136	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        this.clinicService.deleteOwner(owner);
142	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Pet pet = petMapper.toPet(petFieldsDto);
154	        owner.setId(ownerId);
155	        pet.setOwner(owner);
156	        pet.getType().setName(null);
157	        this.clinicService.savePet(pet);
158	        PetDto petDto = petMapper.toPetDto(pet);
159	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
160	            .buildAndExpand(pet.getId()).toUri());
161	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
167	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
168	        if (currentOwner != null) {
169	            Pet currentPet = this.clinicService.findPetById(petId);
170	            if (currentPet != null) {
171	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
172	                currentPet.setName(petFieldsDto.getName());
173	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
174	                this.clinicService.savePet(currentPet);
175	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	            }
177	        }
178	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
184	        HttpHeaders headers = new HttpHeaders();
185	        Visit visit = visitMapper.toVisit(visitFieldsDto);
186	        Pet pet = new Pet();
187	        pet.setId(petId);
188	        visit.setPet(pet);
189	        this.clinicService.saveVisit(visit);
190	        VisitDto visitDto = visitMapper.toVisitDto(visit);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
192	            .buildAndExpand(visit.getId()).toUri());
193	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
194	    }
195	
196	
197	    /**
198	     * Determines whether the given telephone number is already used by any other owner.
199	     *
200	     * @param owner the candidate owner
201	     * @return {@code true} if an owner with the same telephone number already exists in the data store
202	     */
203	    private boolean isDuplicateOwner(Owner owner) {
204	        return this.clinicService.findAllOwners().stream()
205	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
206	    }
207	
208	    /**
209	     * Determines whether the given email address is already used by any other owner. An owner
210	     * without an email address is never considered a duplicate on this criterion. Email addresses
211	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
212	     * surrounding or repeated whitespace.
213	     *
214	     * @param owner the candidate owner
215	     * @return {@code true} if the owner provides an email already used by an existing owner
216	     */
217	    private boolean isDuplicateEmail(Owner owner) {
218	        String email = normalize(owner.getEmail());
219	        if (email.isEmpty()) {
220	            return false;
221	        }
222	        return this.clinicService.findAllOwners().stream()
223	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
224	    }
225	
226	    /**
227	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
228	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
229	     * collapsed to a single space and the result is lower-cased. This is what makes
230	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
231	     * duplicates. A {@code null} value normalizes to the empty string.
232	     *
233	     * @param value the raw value, may be {@code null}
234	     * @return the normalized value, never {@code null}
235	     */
236	    private static String normalize(String value) {
237	        if (value == null) {
238	            return "";
239	        }
240	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner != null) {
248	            Pet pet = owner.getPet(petId);
249	            if (pet != null) {
250	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	}
